projectm_wasm_join_exported_functions() {
    local IFS=,
    echo "${PROJECTM_WASM_EXPORTED_FUNCTIONS[*]}"
}

# EXPORTED_RUNTIME_METHODS for the final wrapper link (common + VFS FS helper).
projectm_wasm_exported_runtime_methods() {
    echo "ccall,cwrap,HEAPF32,HEAPU8,FS,specialHTMLTargets"
}

# SIMD + atomics compile flags for the final emcc link of projectM_emscripten.cpp.
# Must stay in sync with projectm_apply_emscripten_lib_compile_flags() in
# cmake/EmscriptenWasmFlags.cmake so the wrapper TU and prebuilt libprojectM-4.a
# agree on wasm32 feature levels.
projectm_wasm_simd_compile_args() {
    local -n _out=$1
    _out=(
        -msimd128
        -mmutable-globals
        -mbulk-memory
        -matomics
        -mnontrapping-fptoint
        -msign-ext
    )
}

# Code generation semantics (PROJECTM_WASM_CODEGEN_COMPILE_FLAGS in
# cmake/EmscriptenWasmFlags.cmake, which says why each is there). Same for the
# wrapper TUs as for the libraries.
projectm_wasm_codegen_compile_args() {
    local -n _out=$1
    _out=(
        -fno-strict-aliasing
        -fno-math-errno
    )
}

# PROJECTM_WASM_LTO=1 adds -flto to the final wrapper link. The projectM_wasm
# CMake target follows the libraries' own cache entry, so it always matches how
# they were compiled.
#
# PTHREAD_POOL_SIZE is a constant (7): the wrapper's compiled-in
# kWasmPthreadPoolSize and its static_assert must describe the pool the bundle
# really has. An environment override that disagrees is an error, not a knob.
projectm_wasm_pthread_pool_size() {
    if [[ -n "${PROJECTM_WASM_PTHREAD_POOL_SIZE:-}" && "${PROJECTM_WASM_PTHREAD_POOL_SIZE}" != "7" ]]; then
        echo "PROJECTM_WASM_PTHREAD_POOL_SIZE=${PROJECTM_WASM_PTHREAD_POOL_SIZE} is not configurable (this tree's pool is 7); edit cmake/EmscriptenWasmFlags.cmake" >&2
        return 1
    fi
    echo "7"
}


# Restores Module.mainScriptUrlOrBlob so the OffscreenCanvas render worker can
# point the pthread pool at the glue it importScripts()-ed rather than at itself.
projectm_wasm_pthread_script_url_pre_js() {
    local _root
    _root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
    echo "${_root}/src/wasm/pthread_script_url.pre.js"
}

projectm_wasm_common_link_args() {
    local -n _out=$1
    local pthread_pool_size
    pthread_pool_size="$(projectm_wasm_pthread_pool_size)" || return 1
    local pthread_script_url_pre_js
    pthread_script_url_pre_js="$(projectm_wasm_pthread_script_url_pre_js)"

    # Every TU uses native Wasm exceptions (see EmscriptenWasmFlags.cmake).
    if [[ -n "${PROJECTM_WASM_EXCEPTIONS:-}" && "${PROJECTM_WASM_EXCEPTIONS}" != "wasm" ]]; then
        echo "PROJECTM_WASM_EXCEPTIONS=${PROJECTM_WASM_EXCEPTIONS} is no longer supported (always -fwasm-exceptions)" >&2
        return 1
    fi
    local exception_args=(-fwasm-exceptions)

    local lto_args=()
    if [[ "${PROJECTM_WASM_LTO:-0}" == "1" ]]; then
        lto_args+=("-flto")
    fi

    _out=(
        "${lto_args[@]}"
        -std=c++20
        -O3
        -pthread
        -fopenmp=libomp
        "${exception_args[@]}"
        -s SHARED_MEMORY=1
        -s STACK_SIZE=1048576
        -s DEFAULT_PTHREAD_STACK_SIZE=524288
        -s MIN_WEBGL_VERSION=2
        -s MAX_WEBGL_VERSION=2
        -s USE_WEBGL2=1
        -s FULL_ES2=0
        -s FULL_ES3=0
        -s GL_TRACK_ERRORS=0
        -s GL_ENABLE_GET_PROC_ADDRESS=1
        -s ALLOW_MEMORY_GROWTH=0
        -s INITIAL_MEMORY=256mb
        -s MALLOC=mimalloc
        -s ABORTING_MALLOC=0
        -s FORCE_FILESYSTEM=1
        -s "PTHREAD_POOL_SIZE=${pthread_pool_size}"
        -s ENVIRONMENT=web,worker
        -s EXPORT_NAME=createModule
        -s MODULARIZE=1
        -s DEFAULT_TO_CXX=1
        -s INVOKE_RUN=0
        -s EXPORTED_FUNCTIONS="$(projectm_wasm_join_exported_functions)"
        -s EXPORTED_RUNTIME_METHODS="$(projectm_wasm_exported_runtime_methods)"
        --pre-js "${pthread_script_url_pre_js}"
        # <out>.js.symbols: wasm function index -> name, so a production
        # "wasm-function[1234]" stack frame can be symbolized. The .wasm is
        # byte-identical with or without it (no name section is kept).
        --emit-symbol-map
    )
}

projectm_wasm_libomp_args() {
    local root="${1:-}"
    if [[ -f "$root/libomp.a" ]]; then
        echo "$root/libomp.a"
    elif [[ -f "$root/omp/libomp.a" ]]; then
        echo "$root/omp/libomp.a"
    fi
}
